# -*- coding: utf-8 -*-
T=[]
S="writing2"
T.append(dict(id="g2-rp",sec=S,day=5,task="Reporting a classmate",before="Clinic · Reporting a classmate: choose",
 emoji="🎙️",kicker="THE PRESS CONFERENCE",title="Report What<br>They Said",ch1="Press room",
 hook="Welcome to the press room. In an Academic Discussion, you must refer to your classmates' ideas. A good reporter chooses the right verb and keeps the grammar clean. Today you will learn to quote ideas like a professional.",
 A="Ana <b>says me</b> that fees are high.",B="Ana <b>argues</b> that fees are high.",
 cmp="Look at these two sentences. Version A: Ana says me that fees are high. Version B: Ana argues that fees are high. A reporter has to pick the right verb for the message.",
 verdict="Version B is correct. The verb say does not take a person directly, so says me is wrong. Argues that is clear, and it also sounds more academic than says.",
 stampA="MISQUOTED",whyHead="Show that you read your classmates",whySub="Raters check that you respond to their ideas",why="Why does this matter? In this task, raters want to see how you respond to the classmates. Accurate reporting verbs prove that you understood their ideas.",
 rule=[
  dict(legend=["s:reporting verb","v:that + idea"],sub="Choose the verb for the idea",rows=["s:argues|s:claims|s:points out|s:suggests"],say="Do not always write says. Choose the verb that matches the idea. Argues for an opinion. Claims for a statement. Points out for a fact. Suggests for a soft idea."),
  dict(sub="Reporting verb + that",rows=["n:Ana|s:argues|v:that|n:fees are too high"],note="argues that · claims that · points out that",say="Most reporting verbs are followed by that. Ana argues that fees are too high. Ben points out that the plan is cheap. The idea after that is a normal statement."),
  dict(sub="Say or tell?",pair=["say (no person)","Ana <b>said</b> that fees are high.","tell (person)","Ana <b>told me</b> that fees are high."],say="Say does not take a person. Ana said that fees are high. Tell needs a person. Ana told me that fees are high. In a post, argues or claims is usually better than both."),
  dict(sub="Past reports: step back",rows=["n:Ana said that she|v:was|n:against it"],note="is → was · will → would · can → could",say="If you report with a past verb, the tense steps back. Ana said that she was against it. Ben said that he would support the plan. Present reporting verbs, like argues, do not step back."),
  dict(sub="Agree, then add",rows=["n:Ana argues that fees are high.|v:I agree,|n:and I would add…"],note="Report → react → add",say="The best structure: report the idea, react to it, and add something new. Ana argues that fees are high. I agree, and I would add that scholarships are limited.")],
 trap=dict(es="Ana <b>me dice</b> que las tasas son altas.",esnote="decir me = tell me",say1="Now the trap. In Spanish, you say Ana me dice que las tasas son altas. The verb decir takes me directly, and it works for both say and tell.",
  es2="Ana <b>me dice</b> que…",enbad="Ana <b>says me</b> that…",say2="So Spanish speakers write: Ana says me that fees are high. English cannot do that. You must choose tell me, or use a reporting verb with no person.",
  stop="Say that · tell me · argue that",engood="Ana <b>argues that</b> fees are high. Ana <b>told me</b> that…",say3="So, stop. Never write says me. Use argues that, or told me that. And when the reporting verb is past, step the tense back.",
  more=[["Trap 2 · told without me ✗","She <b>told</b> that the class was full.","Fixed ✓","She <b>told me</b> that the class was full.","🔧","The second trap is told without a person. Tell needs someone: she told me, she told us. Without a person, use said."]]),
 quiz=["Ben ___ out that the plan is cheap.",["tells","points","says me"],1],
 quizsay="Quick quiz. Ben, blank, out that the plan is cheap. Which verb makes a phrase with out? ... The answer is B. Points out. A reporting phrase for facts.",
 fix=dict(sub="Fix the sentence",row="n:Ana|g:says me|s:argues|n:that fees are high",say="Fix this one. Ana says me that fees are high. Replace says me with argues: Ana argues that fees are high."),
 recap=["Choose a <b>reporting verb</b>: argues, claims, points out","<b>Say that</b> · <b>tell me</b> · never says me","<b>Report → react → add</b> something new"],
 recapsay="Three things to remember. One, choose a reporting verb like argues, claims or points out. Two, say that, tell me, never says me. Three, report, react, and add something new.",
 done="Great reporting!",donesay="Great reporting! Your classmates' ideas are quoted with style. Go to the practice. Remember: report, react, add. Good luck!",
 check=dict(why1="Points out is a reporting phrase for facts.",q2="Choose the correct sentence.",a2="Ana argues that fees are too high.",w2=["Ana says me that fees are too high.","Ana speaks that fees are too high.","Ana tells that fees are too high."],why2="Say does not take a person.")))
T.append(dict(id="g2-par",sec=S,day=6,task="Parallel structure and comparatives",before="Clinic · Parallel structure and comparatives: choose",
 emoji="👯",kicker="THE TWINS RULE",title="Make Your Lists<br>Identical Twins",ch1="Meet the twins",
 hook="Welcome to the Twins Rule. When you list ideas, they should look like identical twins: the same grammar form every time. Today you will learn to match your lists, and to compare things correctly.",
 A="The plan is cheap, fast and <b>it saves</b> time.",B="The plan is cheap, fast and <b>efficient</b>.",
 cmp="Look at these two sentences. Version A: the plan is cheap, fast and it saves time. Version B: the plan is cheap, fast and efficient. Look at the list. Are the three items twins?",
 verdict="Version B has three twins: cheap, fast, efficient. All are adjectives. Version A suddenly changes form, from adjectives to a whole clause. The list breaks, and the sentence loses its rhythm.",
 stampA="NOT TWINS",whyHead="Parallelism sounds polished",whySub="A mark of advanced, clear writing",why="Why does this matter? Parallel structures make your writing balanced and easy to read. Raters notice when a list is smooth, and also when it is broken.",
 rule=[
  dict(legend=["v:same form"],sub="Same form in a list",rows=["v:reading|v:writing|v:swimming"],say="In a list, every item has the same form. Reading, writing and swimming. All three end in ing. If one of them changes, the list limps."),
  dict(sub="Same form: adjectives",rows=["v:cheap|v:fast|v:efficient"],note="adjective, adjective, adjective",say="The same works with adjectives, nouns and verbs. Cheap, fast and efficient. Three adjectives. Do not add a clause at the end."),
  dict(sub="Not only … but also",rows=["n:Not only|aux:is it|v:cheap,|n:but it is also|v:fast"],note="Both parts must match",say="Not only, but also, needs matching parts. Not only is it cheap, but it is also fast. After not only, the helper comes before the subject, just like in inversion."),
  dict(sub="Comparatives: short and long adjectives",pair=["short: -er","Buses are <b>cheaper</b> than cars.","long: more","Online classes are <b>more flexible</b> than lectures."],say="For comparisons, short adjectives take er: cheaper, quicker, smaller. Long adjectives take more: more flexible, more expensive. Never both. Not more cheaper."),
  dict(sub="Irregular comparatives",rows=["v:good → better|v:bad → worse|v:far → further"],note="Never: more better · more worse",say="A few adjectives are irregular. Good becomes better. Bad becomes worse. Far becomes further. And remember, never more better.")],
 trap=dict(es="<b>No solo</b> es barato<b>, sino</b> también rápido. · <b>más</b> barato que",esnote="Spanish: no solo … sino también · más … que",say1="Now the trap. In Spanish, you say no solo es barato, sino también rápido. And más barato que for comparisons. They look easy to translate.",
  es2="<b>más</b> barato que",enbad="<b>more cheap</b> than",say2="So Spanish speakers write: more cheap than, copying más. English needs the short form: cheaper than. And for not only, they forget the flip: not only it is cheap.",
  stop="Short adjective? -er. Not only? Flip.",engood="<b>Cheaper</b> than · Not only <b>is it</b> cheap…",say3="So, stop. Check adjective length. Short ones take er, long ones take more. And after not only, put the helper before the subject.",
  more=[["Trap 2 · broken list ✗","She likes reading, writing and <b>to swim</b>.","Fixed ✓","She likes reading, writing and <b>swimming</b>.","👯","The second trap is a broken list. If two items end in ing, the third must also end in ing. Reading, writing and swimming."]]),
 quiz=["Buses are ___ than cars.",["more cheap","cheaper","most cheap"],1],
 quizsay="Quick quiz. Buses are, blank, than cars. Cheap is a short adjective. ... The answer is B. Cheaper. Short adjectives take er.",
 fix=dict(sub="Fix the sentence",row="n:She likes reading, writing and|g:to swim|v:swimming",say="Fix this one. She likes reading, writing and to swim. Make the third item match the first two: swimming."),
 recap=["List items have the <b>same form</b>","Short adjective <b>-er</b> · long adjective <b>more</b>","<b>Not only is it</b> … <b>but it is also</b>"],
 recapsay="Three things to remember. One, list items have the same form. Two, short adjectives take er, and long adjectives take more. Three, not only is it, but it is also.",
 done="Perfect twins!",donesay="Perfect twins! Your lists are balanced, and your comparisons are correct. Go to the practice. Good luck!",
 check=dict(why1="Short adjectives take -er.",q2="Choose the correct sentence.",a2="She likes reading, writing and swimming.",w2=["She likes reading, writing and to swim.","She likes to read, writing and swimming.","She likes reading, to write and swimming."],why2="List items need the same form.")))
T.append(dict(id="g2-con",sec=S,day=7,task="Concession structures",before="Clinic · Concession structures: although, despite, while: choose",
 emoji="⚖️",kicker="THE SEESAW",title="Although, Despite,<br>While",ch1="The seesaw",
 hook="Welcome to the seesaw. A strong argument balances two sides: it admits something on the other side, and then pushes back. Today you will learn the three seesaw words, and how each one is built.",
 A="<b>Despite of</b> the cost, the plan is useful.",B="<b>Despite</b> the cost, the plan is useful.",
 cmp="Look at these two sentences. Version A: despite of the cost, the plan is useful. Version B: despite the cost, the plan is useful. One of them has an extra word that tips the seesaw.",
 verdict="Version A has an extra word. Despite never takes of. We say despite the cost, or in spite of the cost. The two forms mean the same, but only in spite takes of.",
 stampA="TIPPED OVER",whyHead="Concession shows you understand both sides",whySub="A signature move of strong posts",why="Why does this matter? Raters love arguments that admit the other side and still make a point. But the grammar of concession is tricky, and Spanish speakers make predictable mistakes.",
 rule=[
  dict(legend=["s:+ clause","v:+ noun or -ing"],sub="Two families",rows=["s:although · even though · while|v:despite · in spite of"],say="Concession words come in two families. Although, even though and while are followed by a clause, with a subject and a verb. Despite and in spite of are followed by a noun or an ing form."),
  dict(sub="Although + clause",rows=["q:Although|s:it is costly,|n:the plan is useful"],note="subject + verb after although",say="Although is followed by a full clause. Although it is costly, the plan is useful. Not although the cost. A clause needs a subject and a verb."),
  dict(sub="Despite + noun or -ing",rows=["q:Despite|s:the cost,|n:the plan is useful"],note="Despite being costly, … · In spite of the delay, …",say="Despite is followed by a noun or an ing form. Despite the cost, the plan is useful. Despite being costly, the plan is useful. And in spite is always followed by of."),
  dict(sub="While: contrast between two ideas",rows=["q:While|s:some prefer cars,|n:others choose buses"],note="While = although / whereas",say="While shows contrast between two ideas. While some prefer cars, others choose buses. It is perfect for summarizing two classmates before giving your own view."),
  dict(sub="Admit, then push back",rows=["n:Admittedly,|s:it is costly.|v:Nevertheless,|n:it is useful."],note="Admittedly… Nevertheless…",say="The seesaw pattern: admit, then push back. Admittedly, it is costly. Nevertheless, it is useful. Or: although it is costly, it is useful. Then return to your position.")],
 trap=dict(es="<b>A pesar de</b> el costo, es útil. · <b>Aunque</b> es caro…",esnote="a pesar de · aunque",say1="Now the trap. In Spanish, a pesar de means despite, and aunque means although. They are simple to translate, so Spanish speakers often translate word by word.",
  es2="<b>a pesar de</b> el costo",enbad="<b>despite of</b> the cost",say2="So they write: despite of the cost. Or: despite it is costly. Or even: although the cost. These errors come from mixing the two families.",
  stop="Clause → although · Noun → despite",engood="<b>Despite</b> the cost… · <b>Although</b> it is costly…",say3="So, stop. Ask: what comes next, a clause or a noun? A clause takes although. A noun takes despite, with no of. In spite always takes of.",
  more=[["Trap 2 · despite + clause ✗","<b>Despite</b> it is costly, it is useful.","Fixed ✓","<b>Although</b> it is costly, it is useful.","🔄","The second trap is despite plus a clause. Despite needs a noun or ing form. With a subject and a verb, use although."],
        ["Trap 3 · although + noun ✗","<b>Although the cost</b>, we paid.","Fixed ✓","<b>Despite the cost</b>, we paid.","🔄","The third trap is although plus a noun. It needs a full clause. Either although it cost a lot, or despite the cost."]]),
 quiz=["___ the cost, the plan is useful.",["Although","Despite","In spite"],1],
 quizsay="Quick quiz. Blank the cost, the plan is useful. A noun follows. ... The answer is B. Despite the cost. Despite takes a noun.",
 fix=dict(sub="Fix the sentence",row="q:Despite|g:of|s:the cost,|n:it is useful",say="Fix this one. Despite of the cost. Delete of. Despite the cost, it is useful."),
 recap=["<b>Although / while</b> + clause","<b>Despite / in spite of</b> + noun or -ing","<b>Despite</b> never takes of · <b>in spite</b> always does"],
 recapsay="Three things to remember. One, although and while take a clause. Two, despite and in spite of take a noun or an ing form. Three, despite never takes of, but in spite always does.",
 done="Balanced!",donesay="Balanced! You can now admit a point and still win the argument. Go to the practice. Remember: clause or noun? Good luck!",
 check=dict(why1="A noun follows despite.",q2="Choose the correct sentence.",a2="Despite the cost, it is useful.",w2=["Despite of the cost, it is useful.","Despite it is costly, it is useful.","Although the cost, it is useful."],why2="Despite takes a noun, with no of.")))
T.append(dict(id="g2-wf",sec=S,day=8,task="Word forms and collocations",before="Clinic · Word forms and collocations: choose",
 emoji="🌳",kicker="THE WORD FAMILY TREE",title="One Root,<br>Many Branches",ch1="The tree",
 hook="Welcome to the word family tree. Every word has relatives: a noun, a verb, an adjective. Using the wrong relative is a common error. Today you will learn to pick the right branch and the right partner.",
 A="It is very <b>benefit</b> for students.",B="It is very <b>beneficial</b> for students.",
 cmp="Look at these two sentences. Version A: it is very benefit for students. Version B: it is very beneficial for students. Both use the same root, but they belong to different branches.",
 verdict="Version B is correct. After very we need an adjective, and the adjective is beneficial. Benefit is the noun. Wrong branch, wrong job.",
 stampA="WRONG BRANCH",whyHead="Precision shows range",whySub="Word forms and collocations raise your vocabulary score",why="Why does this matter? A wrong word form is a very visible error. Choosing the right branch and the right partner shows the rater a wider, more precise vocabulary.",
 rule=[
  dict(legend=["s:noun","v:verb","q:adjective","aux:adverb"],sub="The family",rows=["s:benefit|v:benefit|q:beneficial|aux:beneficially"],say="Here is one family. Benefit as a noun. Benefit as a verb. Beneficial as an adjective. Beneficially as an adverb. Each has its own job in the sentence."),
  dict(sub="Which branch fits?",rows=["n:a|q:beneficial|s:effect","s:Students|v:benefit|n:from the course"],note="adjective before a noun · verb after the subject",say="Check the position. Before a noun, use an adjective: a beneficial effect. After the subject, use a verb: students benefit from the course. The slot tells you the branch."),
  dict(sub="Verb + noun partners",pair=["do","<b>do</b> research · <b>do</b> homework","make","<b>make</b> progress · <b>make</b> a decision"],say="Some verbs belong with certain nouns. We do research, and make progress. We pose a risk, and reach a conclusion. Learn them as pairs, and your writing sounds natural."),
  dict(sub="Academic partners",rows=["v:pose|n:a risk","v:strike|n:a balance","v:reach|n:a conclusion"],note="draw attention · play a role · have an impact",say="Here are three more academic pairs. Pose a risk. Strike a balance. Reach a conclusion. If you use pairs like these, your vocabulary sounds more advanced."),
  dict(sub="A trick for learning",rows=["n:Read|v:→|n:Notice the pair|v:→|q:Use it today"],note="One new pair per post",say="How do you learn pairs? Notice them when you read. Use one new pair in each post you write. In two weeks, you will have fourteen new pairs.")],
 trap=dict(es="<b>Hacer</b> una investigación · <b>hacer</b> progresos",esnote="hacer for everything",say1="Now the trap. In Spanish, the verb hacer pairs with many nouns: hacer una investigación, hacer progresos, hacer una decisión, hacer un riesgo. One verb, many uses.",
  es2="<b>hacer</b> una investigación",enbad="<b>make</b> a research",say2="So Spanish speakers translate hacer as make every time: make a research, make a risk. But English splits the job: do research, make progress, pose a risk.",
  stop="Do not translate the verb",engood="<b>do</b> research · <b>make</b> progress · <b>pose</b> a risk",say3="So, stop. Do not translate hacer automatically. Learn each noun with its own verb, and check the word form after very, a and the.",
  more=[["Trap 2 · the plural ✗","It has many <b>benefit</b>.","Fixed ✓","It has many <b>benefits</b>.","🔧","The second trap is the plural noun. After many, use the plural: many benefits. Check the end of the word."]]),
 quiz=["The plan is very ___ for students.",["benefit","beneficial","benefits"],1],
 quizsay="Quick quiz. The plan is very, blank, for students. After very, we need an adjective. ... The answer is B. Beneficial.",
 fix=dict(sub="Fix the sentence",row="n:The plan|g:makes|v:poses|n:a risk for students",say="Fix this one. The plan makes a risk for students. The partner of risk is pose. The plan poses a risk for students."),
 recap=["Check the <b>branch</b>: noun, verb, adjective, adverb","Learn <b>verb + noun</b> pairs","<b>Do not translate hacer</b>: do research, make progress"],
 recapsay="Three things to remember. One, check the branch: noun, verb, adjective or adverb. Two, learn verb and noun pairs. Three, do not translate hacer: do research, make progress.",
 done="Tree complete!",donesay="Tree complete! You know which branch to pick and which partner to choose. Go to the practice. Good luck!",
 check=dict(why1="After very we need an adjective.",q2="Choose the correct sentence.",a2="The plan poses a risk for students.",w2=["The plan makes a risk for students.","The plan does a risk for students.","The plan puts a risk for students."],why2="Pose a risk is the pair.")))
